<?php namespace App\Filament\Pages;use Filament\Pages\Page;use Illuminate\Support\Facades\DB;
class AcademicAttestationDashboard extends Page{protected static ?string $navigationIcon='heroicon-o-clipboard-check';protected static ?string $navigationLabel='Ведомости и пересдачи';protected static ?string $navigationGroup='Учебная часть';protected static string $view='filament.pages.academic-attestation-dashboard';public array $sheets=[],$stats=[],$retakes=[];public function mount():void{$p=request()->attributes->get('academic_period');if(!$p)return;$pid=$p->id;$this->sheets=DB::table('attestation_sheets as a')->join('study_groups as g','g.id','=','a.study_group_id')->join('subjects as s','s.id','=','a.subject_id')->leftJoin('teachers as t','t.id','=','a.teacher_id')->where('a.academic_period_id',$pid)->select('a.id','a.number','a.assessment_type','a.assessment_date','a.status','g.name as group_name','s.name as subject_name','t.last_name as teacher_name')->orderByDesc('a.id')->limit(50)->get()->map(fn($x)=>(array)$x)->all();$this->stats=['open'=>DB::table('attestation_sheets')->where('academic_period_id',$pid)->where('status','open')->count(),'closed'=>DB::table('attestation_sheets')->where('academic_period_id',$pid)->where('status','closed')->count(),'scheduled'=>DB::table('attestation_attempts as x')->join('attestation_sheets as a','a.id','=','x.attestation_sheet_id')->where('a.academic_period_id',$pid)->where('x.attempt_no','>',0)->whereNull('x.completed_at')->count(),'debts'=>DB::table('attestation_attempts as x')->join('attestation_sheets as a','a.id','=','x.attestation_sheet_id')->where('a.academic_period_id',$pid)->where('x.passed',0)->whereNotNull('x.completed_at')->count()];$this->retakes=DB::table('attestation_attempts as x')->join('attestation_sheets as a','a.id','=','x.attestation_sheet_id')->join('students as st','st.id','=','x.student_id')->join('subjects as sub','sub.id','=','a.subject_id')->where('a.academic_period_id',$pid)->where('x.attempt_no','>',0)->whereNull('x.completed_at')->select('x.id','x.attempt_no','x.scheduled_on','st.last_name','st.first_name','sub.name as subject_name')->orderBy('x.scheduled_on')->limit(20)->get()->map(fn($x)=>(array)$x)->all();}public static function canAccess():bool{$u=auth()->user();return $u&&($u->isSuperAdmin()||$u->hasRole('admin')||$u->hasRole('head_academic')||$u->canDo('semester.mark'));}}